/**
 * The device-clock comparison: the doorbell's own clock against this browser's.
 *
 * The backend exposes no wall-clock field — `/api/health` is
 * `{status, version, uptime_s}` (design 05 §3) — so the only honest reading
 * available to the UI is the `Date` header the device stamps on its own response.
 * That header is generated by the device, at 1-second granularity, which is
 * exactly what makes it useful: comparing it with this browser's clock is what
 * turns "the chime is late" into "the device clock is 47 s behind this browser".
 *
 * Locale-free on purpose, like `clock.ts`: `toLocaleTimeString()` would print
 * differently on the wall panel than in a test, so no test could pin a reading.
 *
 * **Which time zone a reading is printed in.** The header is IMF-fixdate: an
 * instant, not a zone, so it says nothing about where the device thinks it is.
 * A reading is therefore printed in the viewer's own zone (the offset is a
 * parameter, so a test never depends on the machine's `TZ`). That is the honest
 * choice for a comparison: the panel prints this next to the browser's clock, and
 * two readings in different zones would look hours apart while the drift
 * sentence said they agreed. It is also the useful choice, because the kiosk
 * that shows the panel is the very device that owns the speaker (D24), so the
 * browser's zone *is* the device's zone and this prints the doorbell's own
 * wall-clock time.
 *
 * Pure TS, no DOM and no runes: a panel renders, this module decides.
 */

/** Two digits, zero padded. */
function pad(value: number): string {
  return value < 10 ? `0${value}` : String(value);
}

/**
 * Parse an HTTP `Date` header (RFC 7231 IMF-fixdate) into epoch milliseconds;
 * `null` when unusable.
 *
 * `Date.parse` already understands the fixed-width IMF-fixdate the HTTP spec
 * requires, so the whole safety net is rejecting `NaN`: a missing, blank or
 * garbled header must read as "the device did not report a time" rather than as
 * this browser's own clock. Note the header has 1-second granularity, so no
 * caller may claim better than that.
 */
export function parseHttpDate(value: string | null | undefined): number | null {
  if (value === null || value === undefined || value.trim() === '') {
    return null;
  }
  const parsed = Date.parse(value);
  return Number.isNaN(parsed) ? null : parsed;
}

/** Device clock minus browser clock, in seconds (positive = the device is ahead). */
export function driftSeconds(serverTimeMs: number, clientTimeMs: number): number {
  return (serverTimeMs - clientTimeMs) / 1000;
}

/**
 * One honest sentence about the comparison, never a claim of precision it does
 * not have.
 *
 * The reading is whole seconds and the header is only good to a second, so
 * anything rounding to 0 or ±1 is agreement, not drift — reporting "the device
 * clock is 1 s behind" would dress a rounding boundary up as a fact. The sign is
 * worded out loud ("behind"/"ahead") rather than negated twice, and a fractional
 * second is never printed.
 */
export function describeDrift(seconds: number): string {
  const whole = Math.round(seconds);
  if (Math.abs(whole) < 2) {
    return 'the device clock agrees with this browser to within a second';
  }
  if (whole <= -2) {
    return `the device clock is ${-whole} s behind this browser`;
  }
  return `the device clock is ${whole} s ahead of this browser`;
}

/**
 * `HH:MM:SS` for a device clock reading advanced by `elapsedMs`, locale-free.
 *
 * Re-deriving the time from `serverTimeMs + elapsedMs` lets a caller tick the
 * reading locally between reads instead of asking the device once a second.
 *
 * `offsetMinutes` is the zone the reading is printed in, east of UTC (so `+60`
 * prints `22:14` for a `21:14` UTC instant). Omitted, it uses this browser's zone
 * at that instant, which is what the panel wants: the same frame prints the
 * browser's own clock too, and both must be in one zone for the comparison to be
 * readable. Tests always pass an offset explicitly, so no assertion depends on
 * the machine's `TZ`.
 */
export function formatDeviceClock(
  serverTimeMs: number,
  elapsedMs: number,
  offsetMinutes?: number
): string {
  const reading = new Date(serverTimeMs + elapsedMs);
  const offset = offsetMinutes ?? -reading.getTimezoneOffset();
  const shifted = new Date(reading.getTime() + offset * 60_000);
  const hours = pad(shifted.getUTCHours());
  const minutes = pad(shifted.getUTCMinutes());
  const seconds = pad(shifted.getUTCSeconds());
  return `${hours}:${minutes}:${seconds}`;
}
